package com.example.billing;
import static com.example.billing.api.Contracts.*;import static com.example.billing.persistence.BillingSeedData.*;import static org.assertj.core.api.Assertions.*;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;import com.example.billing.service.*;import com.fasterxml.jackson.databind.*;import java.math.*;import java.time.*;import java.util.*;import java.util.concurrent.*;import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.*;import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.http.MediaType;import org.springframework.test.web.servlet.*;
@SpringBootTest @AutoConfigureMockMvc class BillingApplicationTests{@Autowired MockMvc mvc;@Autowired ObjectMapper json;@Autowired UsageService usage;@Autowired com.example.billing.persistence.Repositories.PricePlanRepository plans;String body(Object v)throws Exception{return json.writeValueAsString(v);}SubscriptionResponse subscription(LocalDate start)throws Exception{var x=mvc.perform(post("/subscriptions").contentType(MediaType.APPLICATION_JSON).content(body(new CreateSubscriptionRequest(SAMPLE_CUSTOMER_ID,PRO_PLAN_ID,start)))).andExpect(status().isCreated()).andReturn();return json.readValue(x.getResponse().getContentAsString(),SubscriptionResponse.class);}InvoiceResponse invoice(SubscriptionResponse s)throws Exception{var x=mvc.perform(post("/invoices/generate").contentType(MediaType.APPLICATION_JSON).content(body(new GenerateInvoiceRequest(s.id())))).andExpect(status().isCreated()).andReturn();return json.readValue(x.getResponse().getContentAsString(),InvoiceResponse.class);}@Test void root()throws Exception{assertThat(plans.findById(PRO_PLAN_ID).orElseThrow().billingType).isEqualTo("recurring");mvc.perform(get("/")).andExpect(status().isOk()).andExpect(jsonPath("$.service").value("Billing API"));}@Test void catalogCrudAndValidation()throws Exception{var p=json.readValue(mvc.perform(post("/catalog/products").contentType(MediaType.APPLICATION_JSON).content(body(new CreateProductRequest(" Test "," Desc ",true)))).andExpect(status().isCreated()).andReturn().getResponse().getContentAsString(),ProductResponse.class);assertThat(p.name()).isEqualTo("Test");mvc.perform(put("/catalog/products/{id}",p.id()).contentType(MediaType.APPLICATION_JSON).content(body(new CreateProductRequest("Updated","D",true)))).andExpect(status().isOk());mvc.perform(post("/catalog/price-plans").contentType(MediaType.APPLICATION_JSON).content(body(new CreatePricePlanRequest(p.id(),"recurring",new BigDecimal("2"),"US","month",null)))).andExpect(status().isBadRequest()).andExpect(jsonPath("$.code").value("invalid_price_plan"));}@Test void customerCreateGetListAndDuplicate()throws Exception{var email=UUID.randomUUID()+"@example.com";var req=new CreateCustomerRequest(email,"Acme","Street","pm_1");var x=mvc.perform(post("/customers").contentType(MediaType.APPLICATION_JSON).content(body(req))).andExpect(status().isCreated()).andReturn();var c=json.readValue(x.getResponse().getContentAsString(),CustomerResponse.class);mvc.perform(get("/customers/{id}",c.id())).andExpect(status().isOk());mvc.perform(post("/customers").contentType(MediaType.APPLICATION_JSON).content(body(req))).andExpect(status().isConflict());}@Test void subscriptionsPreserveDatesCancellationAndProration()throws Exception{var s=subscription(LocalDate.of(2026,5,5));assertThat(s.currentPeriodEnd()).isEqualTo(LocalDate.of(2026,6,5));mvc.perform(post("/subscriptions/{id}/cancel",s.id()).contentType(MediaType.APPLICATION_JSON).content(body(new CancelSubscriptionRequest(true)))).andExpect(status().isOk());var p=SubscriptionService.prorate(new BigDecimal("20"),new BigDecimal("50"),LocalDate.of(2026,5,1),LocalDate.of(2026,6,1),LocalDate.of(2026,5,11));assertThat(p.amountDue()).isEqualByComparingTo("20.32");}@Test void invoiceGenerationIsIdempotent()throws Exception{var s=subscription(LocalDate.of(2027,1,1));var first=invoice(s);var second=mvc.perform(post("/invoices/generate").contentType(MediaType.APPLICATION_JSON).content(body(new GenerateInvoiceRequest(s.id())))).andExpect(status().isOk()).andReturn();assertThat(json.readValue(second.getResponse().getContentAsString(),InvoiceResponse.class).id()).isEqualTo(first.id());}@Test void paymentRequiresKeyAndReturnsSamePaymentOnRetry()throws Exception{var inv=invoice(subscription(LocalDate.of(2027,2,1)));mvc.perform(post("/invoices/{id}/pay",inv.id()).contentType(MediaType.APPLICATION_JSON).content("{}")).andExpect(status().isBadRequest());var key=UUID.randomUUID().toString();var first=mvc.perform(post("/invoices/{id}/pay",inv.id()).header("Idempotency-Key",key).contentType(MediaType.APPLICATION_JSON).content("{}")).andExpect(status().isCreated()).andReturn();var p=json.readValue(first.getResponse().getContentAsString(),PaymentResponse.class);var second=mvc.perform(post("/invoices/{id}/pay",inv.id()).header("Idempotency-Key",key).contentType(MediaType.APPLICATION_JSON).content("{}")).andExpect(status().isOk()).andReturn();assertThat(json.readValue(second.getResponse().getContentAsString(),PaymentResponse.class).id()).isEqualTo(p.id());}@Test void samePaymentKeyWithDifferentBodyIsRejected()throws Exception{var inv=invoice(subscription(LocalDate.of(2027,3,1)));var key=UUID.randomUUID().toString();mvc.perform(post("/invoices/{id}/pay",inv.id()).header("Idempotency-Key",key).contentType(MediaType.APPLICATION_JSON).content(body(new PayInvoiceRequest("one",true)))).andExpect(status().isBadGateway());mvc.perform(post("/invoices/{id}/pay",inv.id()).header("Idempotency-Key",key).contentType(MediaType.APPLICATION_JSON).content(body(new PayInvoiceRequest("two",true)))).andExpect(status().isConflict());}@Test void concurrentDuplicatePaymentCreatesOneCharge()throws Exception{var inv=invoice(subscription(LocalDate.of(2027,4,1)));var key=UUID.randomUUID().toString();try(var pool=Executors.newFixedThreadPool(2)){var task=(Callable<MvcResult>)()->mvc.perform(post("/invoices/{id}/pay",inv.id()).header("Idempotency-Key",key).contentType(MediaType.APPLICATION_JSON).content("{}")).andReturn();var results=pool.invokeAll(List.of(task,task));var ids=new HashSet<String>();for(var f:results){var r=f.get().getResponse();assertThat(r.getStatus()).isIn(200,201);ids.add(json.readTree(r.getContentAsString()).get("id").asText());}assertThat(ids).hasSize(1);}}@Test void usageIsIdempotentAndHalfOpenPeriod()throws Exception{var id=subscription(LocalDate.of(2027,5,1)).id();var key=UUID.randomUUID().toString();var at=OffsetDateTime.parse("2027-05-02T00:00:00Z");var req=new ReportUsageRequest(id," API_CALL ",new BigDecimal("12.5"),at);var one=usage.report(req,key);assertThat(usage.report(req,key).id()).isEqualTo(one.id());assertThat(usage.list(id,at,at.plusDays(1))).hasSize(1);}}
